const foods = w => {
  const de = [];
  for (const f of (w.style?.food || [])) {
    const m = FOOD_DE[String(f?.name || '').trim().toLowerCase()];
    if (m && !de.includes(m)) de.push(m);
  }
  return de;
};
const grapes = w => [...new Set((w.style?.grapes || []).map(g => String(g?.name || '').trim()).filter(Boolean))].join(', ');

// Flaschenfoto (bevorzugt mittlere Grösse), Adresse beginnt bei Vivino mit "//".
const imageUrl = v => {
  const u = v.image?.variations?.bottle_medium || v.image?.variations?.large || v.image?.variations?.medium || v.image?.location || '';
  return u.startsWith('//') ? 'https:' + u : (u.startsWith('https://') ? u : '');
};

const get = path => new Promise((resolve, reject) => {
  const req = https.get({ host: 'www.vivino.com', path, headers: { 'User-Agent': UA, 'Accept': 'application/json' }, timeout: 15000 }, res => {
    let data = '';
    res.on('data', c => { data += c; });
    res.on('end', () => resolve({ status: res.statusCode, data }));
  });
  req.on('timeout', () => req.destroy(new Error('Zeitüberschreitung')));
  req.on('error', reject);
});

try {
  const body = $input.first().json.body || {};
  const term = String(body.term || '').trim().slice(0, 60);
  if (term.length < 2) return [{ json: { ok: false, meldung: 'Suchwort fehlt.' } }];

  // Bremse: höchstens 30 Abfragen pro Stunde, damit der Weg nicht zum Dauerabruf wird.
  const sd = $getWorkflowStaticData('global');
  const now = Date.now();
  sd.calls = (sd.calls || []).filter(t => now - t < 3600e3);
  if (sd.calls.length >= 30) return [{ json: { ok: false, meldung: 'Zu viele Abfragen in der letzten Stunde.' } }];
  sd.calls.push(now);

  const out = new Map();
  let matched = 0;
  for (let page = 1; page <= 2; page++) {
    const r = await get('/api/explore/explore?search_term=' + encodeURIComponent(term) + '&min_rating=0&country_code=CH&page=' + page);
    if (r.status !== 200) return [{ json: { ok: false, meldung: 'Vivino antwortet mit ' + r.status + '.' } }];
    let data;
    try { data = JSON.parse(r.data); } catch (e) { return [{ json: { ok: false, meldung: 'Antwort von Vivino ist kein gültiges JSON.' } }]; }
    const ev = data?.explore_vintage;
    matched = ev?.records_matched ?? matched;
    for (const m of (ev?.matches || [])) {
      const v = m.vintage, w = v.wine;
      const vid = String(v.id);
      if (out.has(vid)) continue;
      out.set(vid, {
        vid, wineId: String(w.id),
        name: w.name || '', producer: w.winery?.name || '',
        vintage: Number.isInteger(v.year) ? v.year : 0,
        region: w.region?.name || w.region?.name_en || '',
        country: land(w.region?.country),
        typeRaw: TYPES[w.type_id] || '',
        grape: grapes(w), foodPairings: foods(w),
        rating: v.statistics?.ratings_average ?? null,
        ratingsCount: v.statistics?.ratings_count ?? 0,
        imageURL: imageUrl(v),
      });
    }
    if (page * 24 >= matched || !(ev?.matches || []).length) break;
    await new Promise(res => setTimeout(res, 1500));
  }
  return [{ json: { ok: true, term, matched, candidates: [...out.values()] } }];
} catch (e) {
  return [{ json: { ok: false, meldung: 'Abfrage fehlgeschlagen: ' + String(e.message).replace(/[_*`\[\]]/g, ' ') } }];
}
